import limited_client as robot, numpy as np
for c in ('topview','corner','corner2'):
 o=robot.observe(c); d=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world'];
 print('\n',c)
 for u,v in ([(250,266),(290,266),(325,266),(340,280),(340,180),(340,145),(350,150),(340,320)] if c=='topview' else [(140,155),(145,210),(185,260),(215,250),(250,260),(130,240)]):
  patch=d[max(v-2,0):v+3,max(u-2,0):u+3]; z=float(np.median(patch)); p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]); w=T@p
  print((u,v),round(z,3),np.round(w[:3],3))
